using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using FleetOps.Kernel.Authorization;
using FleetOps.Modules.Fleet;
using Npgsql;
using Xunit;

namespace FleetOps.Tests;

public sealed class VehicleTests : IAsyncLifetime
{
    private readonly VehicleApiFactory factory = new();
    public ValueTask InitializeAsync() => factory.InitializeAsync();
    public ValueTask DisposeAsync() => factory.DisposeAsync();

    [Fact] public async Task Dispatcher_adds_a_truck_and_required_documents_are_listed() { using var c = factory.AsDispatcher(); var v = await factory.CreateTruck(c); Assert.Equal(6, v.RequiredDocuments.Count); }
    [Fact] public async Task Owner_adds_a_truck() { using var c = factory.AsOwner(); Assert.Equal(VehicleKind.Truck, (await factory.CreateTruck(c)).Kind); }
    [Fact] public async Task Trailer_lists_trailer_documents_and_flags_sp() { using var c = factory.AsOwner(); var v = await CreateTrailer(c); Assert.Contains(v.RequiredDocuments, x => x.Type == "SP" && x.NeedsConfirmation); }
    [Fact] public async Task Truck_at_or_under_7500_kg_does_not_list_sp() { using var c = factory.AsOwner(); Assert.DoesNotContain((await factory.CreateTruck(c, grossWeightKg: 7500)).RequiredDocuments, x => x.Type == "SP"); }
    [Fact] public async Task Hr_cannot_add_a_vehicle_and_nothing_is_written() { using var c = factory.AsHr(); var before = await factory.CountRows("vehicles"); using var r = await Post(c); Assert.Equal(HttpStatusCode.Forbidden, r.StatusCode); Assert.Equal("permission_denied", await Code(r)); Assert.Equal(before, await factory.CountRows("vehicles")); }
    [Fact] public async Task Driver_cannot_add_a_vehicle_and_nothing_is_written() { using var c = factory.AsDriver(); var before = await factory.CountRows("vehicles"); using var r = await Post(c); Assert.Equal(HttpStatusCode.Forbidden, r.StatusCode); Assert.Equal("permission_denied", await Code(r)); Assert.Equal(before, await factory.CountRows("vehicles")); }
    [Fact] public async Task Invalid_plate_lists_the_field_name_and_not_the_value() { using var c = factory.AsOwner(); using var r = await Post(c, plate: "bad"); var body = await r.Content.ReadAsStringAsync(); Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); Assert.Contains("plate", body); Assert.DoesNotContain("bad", body); }
    [Fact] public async Task Invalid_vin_is_refused() { using var c = factory.AsOwner(); using var r = await Post(c, vin: "I".PadRight(17, '1')); Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); Assert.Contains("vin", await r.Content.ReadAsStringAsync()); }
    [Fact] public async Task Missing_required_field_is_refused() { using var c = factory.AsOwner(); using var r = await Post(c, make: ""); Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); Assert.Contains("make", await r.Content.ReadAsStringAsync()); }
    [Fact] public async Task Duplicate_plate_is_refused() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); using var r = await Post(c, plate: v.Plate); Assert.Equal(HttpStatusCode.Conflict, r.StatusCode); Assert.Equal("duplicate_vehicle", await Code(r)); }
    [Fact] public async Task Duplicate_vin_is_refused() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); using var r = await Post(c, vin: v.Vin); Assert.Equal(HttpStatusCode.Conflict, r.StatusCode); Assert.Equal("duplicate_vehicle", await Code(r)); }
    [Fact] public async Task Plate_change_keeps_the_old_plate_in_history() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); var changed = await Edit(c, v, plate: "B-H 9998"); using var r = await c.GetAsync($"/api/v1/fleet/vehicles/{v.Id}"); var current = await r.Content.ReadFromJsonAsync<VehicleDetail>(); Assert.Equal(changed.Plate, current!.Plate); Assert.Contains(v.Plate, current.PlateHistory); }
    [Fact] public async Task Plate_change_requires_a_reason() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); using var r = await Put(c, v, plate: "B-H 9997", reason: ""); Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); Assert.Contains("reason", await r.Content.ReadAsStringAsync()); }
    [Fact] public async Task Leased_vehicle_returns_ownership_and_end_date() { using var c = factory.AsOwner(); using var r = await Post(c, ownership: 1, leaseEndDate: "2030-01-01"); var v = await r.Content.ReadFromJsonAsync<VehicleDetail>(); Assert.Equal(VehicleOwnership.Leased, v!.Ownership); Assert.Equal(new DateOnly(2030, 1, 1), v.LeaseEndDate); }
    [Fact] public async Task Lease_end_date_is_refused_for_owned_vehicles() { using var c = factory.AsOwner(); using var r = await Post(c, leaseEndDate: "2030-01-01"); Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); Assert.Contains("leaseEndDate", await r.Content.ReadAsStringAsync()); }
    [Fact] public async Task Trailer_type_is_refused_on_a_truck() { using var c = factory.AsOwner(); using var r = await Post(c, trailerType: 1); Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); Assert.Contains("trailerType", await r.Content.ReadAsStringAsync()); }
    [Fact] public async Task Odometer_is_refused_on_a_trailer() { using var c = factory.AsOwner(); using var r = await Post(c, kind: 1, trailerType: 1, odometerKm: 1); Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); Assert.Contains("odometerKm", await r.Content.ReadAsStringAsync()); }
    [Fact] public async Task Stale_version_is_refused_and_nothing_is_overwritten() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); using var r = await Put(c, v, version: v.Version - 1, make: "BROKEN"); Assert.Equal(HttpStatusCode.Conflict, r.StatusCode); Assert.Equal("version_conflict", await Code(r)); using var get = await c.GetAsync($"/api/v1/fleet/vehicles/{v.Id}"); Assert.Equal(v.Make, (await get.Content.ReadFromJsonAsync<VehicleDetail>())!.Make); }
    [Fact] public async Task Stale_version_writes_no_audit_entry() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); var before = await factory.CountRows("audit_entries"); using var r = await Put(c, v, version: v.Version - 1, make: "BROKEN"); Assert.Equal(HttpStatusCode.Conflict, r.StatusCode); Assert.Equal(before, await factory.CountRows("audit_entries")); }
    [Fact] public async Task Version_increases_on_each_edit() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); var one = await Edit(c, v, make: "DAF"); var two = await Edit(c, one, make: "IVECO"); Assert.True(two.Version > one.Version); using var get = await c.GetAsync($"/api/v1/fleet/vehicles/{v.Id}"); Assert.Equal(two.Version, (await get.Content.ReadFromJsonAsync<VehicleDetail>())!.Version); }
    [Fact] public async Task Vehicle_change_writes_audit_with_actor_and_reason_in_the_same_transaction() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); var reason = "same transaction reason"; await Edit(c, v, make: "DAF", model: "XF", reason: reason); await using var db = await factory.DirectConnection(); await using var q = new NpgsqlCommand("select actor_id, reason from fleetops.audit_entries where entity_id = @id and reason = @reason", db); q.Parameters.AddWithValue("id", v.Id); q.Parameters.AddWithValue("reason", reason); await using var rows = await q.ExecuteReaderAsync(); Assert.True(await rows.ReadAsync()); Assert.Equal("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa", rows.GetString(0)); Assert.Equal(reason, rows.GetString(1)); await rows.CloseAsync(); var beforeVehicles = await factory.CountRows("vehicles"); var beforeAudits = await factory.CountRows("audit_entries"); factory.ThrowAfterWrite = true; using var failed = await Post(c); Assert.Equal(HttpStatusCode.InternalServerError, failed.StatusCode); Assert.Equal(beforeVehicles, await factory.CountRows("vehicles")); Assert.Equal(beforeAudits, await factory.CountRows("audit_entries")); }
    [Fact] public async Task Failure_after_the_write_rolls_back_vehicle_and_audit() { using var c = factory.AsOwner(); var vehicles = await factory.CountRows("vehicles"); var audits = await factory.CountRows("audit_entries"); factory.ThrowAfterWrite = true; using var r = await Post(c); Assert.Equal(HttpStatusCode.InternalServerError, r.StatusCode); Assert.Equal(vehicles, await factory.CountRows("vehicles")); Assert.Equal(audits, await factory.CountRows("audit_entries")); }
    [Fact] public async Task Each_changed_field_gets_one_audit_entry_and_unchanged_fields_none() { using var c = factory.AsOwner(); var v = await factory.CreateTruck(c); var before = await factory.CountRows("audit_entries"); await Edit(c, v, make: "DAF", model: "XF", reason: "two fields"); await using var db = await factory.DirectConnection(); await using var q = new NpgsqlCommand("select field_name from fleetops.audit_entries where entity_id = @id order by field_name", db); q.Parameters.AddWithValue("id", v.Id); await using var rows = await q.ExecuteReaderAsync(); var fields = new List<string>(); while (await rows.ReadAsync()) fields.Add(rows.GetString(0)); Console.WriteLine($"AUDIT FIELD NAMES: {string.Join(", ", fields)}"); Assert.Equal(2, fields.Count(x => x is "Make" or "Model")); Assert.DoesNotContain("Plate", fields); Assert.Equal(before + 2, await factory.CountRows("audit_entries")); }
    [Fact] public async Task Runtime_role_cannot_update_or_delete_audit_entries() { await using var db = await factory.DirectConnection(); await using var select = new NpgsqlCommand("select count(*) from fleetops.audit_entries", db); Assert.True((long)(await select.ExecuteScalarAsync()) >= 0); await using var insert = new NpgsqlCommand("insert into fleetops.audit_entries values (@id, 'Vehicle', @entity, 'Make', 'actor', 'reason', now())", db); insert.Parameters.AddWithValue("id", Guid.CreateVersion7()); insert.Parameters.AddWithValue("entity", Guid.CreateVersion7()); await insert.ExecuteNonQueryAsync(); foreach (var sql in new[] { "update fleetops.audit_entries set reason = 'x'", "delete from fleetops.audit_entries" }) { await using var command = new NpgsqlCommand(sql, db); var ex = await Assert.ThrowsAsync<PostgresException>(() => command.ExecuteNonQueryAsync()); Assert.Equal("42501", ex.SqlState); } }
    [Fact] public async Task Default_depot_is_used() { using var c = factory.AsOwner(); Assert.NotEqual(Guid.Empty, (await factory.CreateTruck(c)).DepotId); }

    private async Task<VehicleDetail> CreateTrailer(HttpClient c) { using var r = await Post(c, kind: 1, trailerType: 1, odometerKm: null); r.EnsureSuccessStatusCode(); return (await r.Content.ReadFromJsonAsync<VehicleDetail>())!; }
    private Task<HttpResponseMessage> Post(HttpClient c, string? plate = null, string? vin = null, string make = "MAN", int kind = 0, int? trailerType = null, int? odometerKm = 1000, int ownership = 0, string? leaseEndDate = null) => c.PostAsJsonAsync("/api/v1/fleet/vehicles", new { kind, plate = plate ?? $"B-X {Random.Shared.Next(1000, 9999)}", vin = vin ?? $"WVWZZZ1JZXW{Random.Shared.Next(100000, 999999)}", make, model = "TGX", year = 2020, grossWeightKg = 8000, requiredLicenceClass = "C", ownership, leaseEndDate, trailerType, odometerKm, depotId = (Guid?)null, serviceIntervalKm = 50000, serviceIntervalMonths = 12, lastTachoDownloadAt = (string?)null, reason = "reason" }, TestContext.Current.CancellationToken);
    private async Task<VehicleDetail> Edit(HttpClient c, VehicleDetail v, string? plate = null, string? make = null, string? model = null, int? version = null, string reason = "edit reason") { using var r = await Put(c, v, plate, make, model, version, reason); r.EnsureSuccessStatusCode(); return (await r.Content.ReadFromJsonAsync<VehicleDetail>())!; }
    private Task<HttpResponseMessage> Put(HttpClient c, VehicleDetail v, string? plate = null, string? make = null, string? model = null, int? version = null, string reason = "edit reason") => c.PutAsJsonAsync($"/api/v1/fleet/vehicles/{v.Id}", new { version = version ?? v.Version, kind = (int)v.Kind, plate = plate ?? v.Plate, vin = v.Vin, make = make ?? v.Make, model = model ?? v.Model, year = v.Year, grossWeightKg = v.GrossWeightKg, requiredLicenceClass = "C", ownership = (int)v.Ownership, leaseEndDate = v.LeaseEndDate, trailerType = (int?)v.TrailerType, odometerKm = v.OdometerKm, depotId = v.DepotId, serviceIntervalKm = 50000, serviceIntervalMonths = 12, lastTachoDownloadAt = (string?)null, reason }, TestContext.Current.CancellationToken);
    private async Task<string?> Code(HttpResponseMessage response) { using var document = JsonDocument.Parse(await response.Content.ReadAsStringAsync()); return document.RootElement.TryGetProperty("code", out var code) ? code.GetString() : null; }
}
